param([Parameter(Mandatory=$true)][string]$Executable,[string]$Label='dev4')
# Windows STA harness. Only isolated fixtures are edited; launches are intercepted.
. "$PSScriptRoot\enhancement-ui-common.ps1"
Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase,System.Xaml
$bin=Split-Path $Executable -Parent
$framework=Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319';$wpf=Join-Path $framework 'WPF'
$refs=@('System.dll','System.Core.dll','System.Xaml.dll','System.Web.Extensions.dll','System.Windows.Forms.dll','System.Drawing.dll')|ForEach-Object {Join-Path $framework $_}
$refs+=@('PresentationFramework.dll','PresentationCore.dll','WindowsBase.dll')|ForEach-Object {Join-Path $wpf $_}
$refs+=@('GUNT.ControlCenter.exe','Gunt.Configuration.dll','Gunt.Sensors.dll')|ForEach-Object {$file=Join-Path $bin $_;$null=[Reflection.Assembly]::LoadFrom($file);$file}
$fixture=Join-Path $Root ('tests\launchpad-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force (Join-Path $fixture 'config'),(Join-Path $fixture 'state'),(Join-Path $fixture 'logs'),(Join-Path $fixture 'assets')|Out-Null
Copy-Item (Join-Path $Root 'assets\branding') (Join-Path $fixture 'assets') -Recurse
foreach($name in @('theme','topbar','startup','ux')){Copy-Item (Join-Path $Root ('config\'+$name+'.json')) (Join-Path $fixture 'config')}
$code=@'
using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Input;using System.Windows.Interop;using System.Windows.Media;using System.Windows.Threading;using System.Runtime.InteropServices;using Gunt.ControlCenter.Models;using Gunt.ControlCenter.Services;using Gunt.ControlCenter.Views;
public static class LaunchpadChecks {
 static readonly List<string> checks=new List<string>();static Exception dispatchError;
 static void Check(bool test,string name){if(!test)throw new Exception("FAIL: "+name);checks.Add(name);}
 static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(o,v);}
 static object Call(object o,string n,params object[] a){try{return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}catch(TargetInvocationException e){throw e.InnerException;}}
 static void Pump(int ms){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);if(dispatchError!=null)throw dispatchError;}
 static void Wait(Func<bool> condition){for(int i=0;i<200&&!condition();i++)Pump(30);Check(condition(),"background operation completed");}
 static void Reject(Action action,string name){try{action();}catch(ArgumentException){Check(true,name);return;}catch(FileNotFoundException){Check(true,name);return;}catch(InvalidOperationException){Check(true,name);return;}throw new Exception("Expected rejection: "+name);}
 public static string[] Run(string root){var service=new DesktopService(root);Directory.CreateDirectory(Path.Combine(root,"demo"));File.WriteAllText(Path.Combine(root,"config","projects.json"),"{\"SchemaVersion\":2,\"Projects\":[]}");
  uint modifiers,key;Check(GuntLaunchpadHotkey.TryParse("Ctrl+Alt+L",out modifiers,out key)&&key==76,"hotkey parser default");Check(!GuntLaunchpadHotkey.TryParse("L",out modifiers,out key),"unmodified key rejected");Check(!GuntLaunchpadHotkey.TryParse("Ctrl+Ctrl+L",out modifiers,out key),"duplicate modifier rejected");
  Check(GuntLaunchpadHotkey.RegisterHotKey(IntPtr.Zero,194,0x4003,0x7B),"reserve test hotkey Ctrl Alt F12");try{Check(!GuntLaunchpadHotkey.Probe("Ctrl+Alt+F12"),"actual Windows hotkey collision detected");}finally{GuntLaunchpadHotkey.UnregisterHotKey(IntPtr.Zero,194);}
  var config=service.Launchpad();service.SaveLaunchpad(config);var stale=service.Launchpad();var fresh=service.Launchpad();fresh.IconSize=56;service.SaveLaunchpad(fresh);Reject(()=>service.SaveLaunchpad(stale),"stale write rejected");
  var app=new ApplicationEntry{Id="custom-safe",Name="문서 예제",Kind="website",Target="https://example.com",Source="사용자",Category="internet",Arguments=new string[0]};DesktopService.ValidateApplication(app,true);Check(true,"HTTP target validated");Reject(()=>DesktopService.ValidateApplication(new ApplicationEntry{Name="invalid",Kind="website",Target="file:///C:/Windows",Arguments=new string[0]},true),"non HTTP scheme rejected");Reject(()=>DesktopService.ValidateApplication(new ApplicationEntry{Name="invalid",Kind="exe",Target="powershell.exe",Arguments=new string[0]},true),"relative executable rejected");Reject(()=>DesktopService.ValidateApplication(new ApplicationEntry{Name="invalid",Kind="exe",Target=Path.Combine(root,"missing.exe"),Arguments=new string[0]},true),"missing target rejected");
  var c=service.Launchpad();c.Shortcuts.Add(app);c.Categories.Add(new LaunchpadCategory{Id="custom-category",Name="검증"});c.Folders.Add(new LaunchpadFolder{Id="group-tools",Name="도구",Category="utilities"});var state=DesktopService.Item(c,app.Id);state.Favorite=true;state.Category="custom-category";state.Aliases="샘플";service.SaveLaunchpad(c);Check(service.Launchpad().Items[app.Id].Favorite,"favorite persisted");Check(DesktopService.FilterApplications(new[]{app},c,"all",null,"샘플").Length==1,"alias search uses shared matcher");DesktopService.DeleteLaunchpadCategory(c,"custom-category");Check(c.Items[app.Id].Category=="utilities"&&c.Shortcuts.Count==1,"category deletion preserves shortcut");state.Folder="group-tools";Check(DesktopService.FilterApplications(new[]{app},c,"utilities","group-tools","").Length==1,"folder membership filters");DesktopService.DeleteLaunchpadFolder(c,"group-tools");Check(state.Folder==null,"folder deletion preserves apps");Reject(()=>DesktopService.DeleteLaunchpadCategory(c,"all"),"system category deletion rejected");service.SaveLaunchpad(c);
  int launches=0;service.LaunchOverride=info=>{launches++;Check(info.FileName=="https://example.com"&&info.UseShellExecute,"safe shell launch target");};service.LaunchApplication(app);Check(launches==1,"launch request goes through shared service");
  var catalog=new ApplicationCatalog{Refreshed=DateTimeOffset.Now.ToString("o")};for(int i=0;i<1000;i++)catalog.Apps.Add(new ApplicationEntry{Id="test-"+i,Name="검증 앱 "+i.ToString("0000"),Kind="website",Target="https://example.com",Source="검증",Category="utilities",Context="웹사이트"});File.WriteAllText(Path.Combine(root,"state","launchpad-catalog.json"),service.Json.Serialize(catalog));
  var application=Application.Current??new Application();application.ShutdownMode=ShutdownMode.OnExplicitShutdown;application.DispatcherUnhandledException+=delegate(object sender,DispatcherUnhandledExceptionEventArgs e){dispatchError=e.Exception;e.Handled=true;};var win=new LaunchpadWindow(root);
  try{win.Show();Pump(200);Wait(()=>((ApplicationEntry[])Field(win,"entries")).Length>1000);var grid=(UniformGrid)Field(win,"grid");Check(grid.Children.Count>0&&grid.Children.Count<=32,"1000 apps construct visible page only");var search=(TextBox)Field(win,"search");search.Text="검증 앱 0999";Pump(120);Check(((ApplicationEntry[])Field(win,"visible")).Length==1,"instant in-memory search");search.Text="";Pump(100);Call(win,"MoveApp","test-0","favorites",null);Check(service.Launchpad().Items["test-0"].Favorite,"category drop favorites persistence");Call(win,"Reorder","test-1","test-0");Check(service.Launchpad().Items["test-1"].Order<service.Launchpad().Items["test-0"].Order,"reordering persisted");
   Call(win,"MoveApp","test-1","development",null);Check(service.Launchpad().Items["test-1"].Category=="development","category move persists");
   var nested=service.Launchpad();nested.Folders.Add(new LaunchpadFolder{Id="group-check",Name="검증 폴더",Category="utilities"});service.SaveLaunchpad(nested);Set(win,"config",service.Launchpad());Call(win,"MoveApp","test-2","utilities","group-check");Check(service.Launchpad().Items["test-2"].Folder=="group-check","folder move persists");Call(win,"MoveApp","test-2","utilities",null);Check(service.Launchpad().Items["test-2"].Folder==null,"folder extraction persists");
   Set(win,"requestBusy",false);win.Present();Pump(150);Check(search.IsKeyboardFocusWithin,"opening focuses search");Call(win,"Dismiss");Check(!win.IsVisible,"hide preserves instance");win.Present();Pump(100);Check(win.IsVisible,"same window warm reopen");var h=new WindowInteropHelper(win).Handle;var screen=System.Windows.Forms.Screen.FromHandle(h);var point=win.PointToScreen(new Point());Check(point.X>=screen.WorkingArea.Left-2&&point.Y>=screen.WorkingArea.Top-2&&point.X+win.ActualWidth*GuntLayout.Scale(screen)<=screen.WorkingArea.Right+2,"work area containment on actual DPI");
   var iconService=new LaunchpadIcons(root);Check(iconService.PosePath("invalid",128)==null,"unknown mascot pose fallback");Check(File.Exists(iconService.PosePath("default",128)),"approved mascot fallback exists");var imageTask=iconService.Get(app,"invalid",true);Wait(()=>imageTask.IsCompleted);Check(imageTask.Result.IsFrozen,"icon source frozen across threads");
  }finally{Set(win,"terminating",true);win.Close();}
  var discovery=service.DiscoverApplicationsAsync();Wait(()=>discovery.IsCompleted);Check(!discovery.IsFaulted&&discovery.Result.Apps.Count>0,"real Start Menu and AppsFolder enumeration");Check(discovery.Result.Apps.Select(x=>x.Id).Distinct().Count()==discovery.Result.Apps.Count,"stable discovery IDs unique");Check(discovery.Result.Apps.All(x=>x.Kind=="shortcut"||x.Kind=="packaged"),"discovery uses supported sources only");
  return checks.ToArray();
 }
}
'@
$provider=New-Object Microsoft.CSharp.CSharpCodeProvider
$parameters=New-Object CodeDom.Compiler.CompilerParameters
$parameters.GenerateInMemory=$true
$parameters.ReferencedAssemblies.AddRange([string[]]$refs)
$compiled=$provider.CompileAssemblyFromSource($parameters,$code)
if($compiled.Errors.HasErrors){throw ($compiled.Errors|Out-String)}
$null=$compiled.CompiledAssembly
try{$checks=[LaunchpadChecks]::Run($fixture);Write-Json @{Label=$Label;Passed=$checks.Count;Checks=$checks;ExecutableSha256=(Get-FileHash $Executable).Hash;Fixture=$fixture;CapturedAt=[DateTimeOffset]::Now.ToString('o')} (Join-Path $Root ('logs\launchpad-'+$Label+'-tests.json'));Write-Output ($checks.Count.ToString()+' checks passed')}catch{[IO.File]::WriteAllText((Join-Path $Root ('logs\launchpad-'+$Label+'-failure.txt')),$_.Exception.ToString());throw}
